      "Jaune				1000 g",
      "Blancs				500 g",
      "Miel de lavande		50 g",
      "Mélanger ensemble.",
      "Pâte fermentée :",
      "Farine				1000 g",
      "Sel				18 g",
      "Levure				6 g",
      "Eau				 650 g + 20 g",
      "Pétrir la farine, le sel, la levure, et l’eau 4 minutes en première et 5 minutes en deuxième. Ajouter les 20 g d’eau puis pétrir 3 minutes en deuxième. Laisser pointer une heure à température ambiante, puis réserver en chambre froide. Cette pâte ce conserve 3 jour en chambre froide.",
      "Le mieux pour la pâte fermentée est d’utiliser la pâte restante de la veille. Et de la laisser fermentée 24 heures en chambre froide.",
