      "Pétrir tous les ingrédients sauf le beurre tourage 2 minutes en première, puis 8 minutes en deuxième. Abaisser en plaque de 40cm/60cm, puis passer au congélateur afin que la pâte durcisse. Étaler la pâte en rectangle de 40cm/60cm, puis étaler le beurre tempéré sur les 2/3 du pâton puis donner un tour simple. Donner ensuite 1 tour simple. Stocker les pâtons au congélateur, afin de bien les faire refroidir. Etaler les pâtons au laminoir afin d’obtenir une abaisse de 1m25/30cm (3-4mm). Etaler dessus 100 g de tapenade sur toute la surface et parsemer 550 g d’olives hachées (dessalées si besoin) 2 bocaux d’olives + 2 bocaux de tapenade = 5*550g. Détailler ensuite des pâtons de 25 cm de largueur et les rouler bien serrés. Stocker au congélateur. Sortir les boudins en fonction de l’activité puis détailler des tronçons de 2.5cm de largueur (40 g). Laisser pousser au panem à 28°C pendant environ 15 minutes. Cuire à 200°C pendant 2x6 minutes, puis à la sortie du four asperger généreusement d’huile d’olive.",
